"""Translate pinned Go behavioral vectors to portable MoonBit black-box tests."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def shard(encoded):
    return 'b"' + ''.join(f'\\x{value:02x}' for value in bytes.fromhex(encoded)) + '"'


def array(values):
    return '[' + ', '.join(values) + ']'


def main():
    fixture = json.loads((ROOT / 'testdata/reedsolomon-v1.14.2.json').read_text())
    assert fixture['reference'] == 'github.com/klauspost/reedsolomon@v1.14.2'
    lines = [
        '// Generated by tools/generate_reference_tests.py; exclude from handwritten LOC.',
        '// Behavioral reference: klauspost/reedsolomon v1.14.2, default GF(256) matrix.',
        '// See THIRD_PARTY_NOTICES.md and docs/REFERENCE_COMPARISON.md.',
    ]
    for i, v in enumerate(fixture['vectors']):
        encoded = [shard(h) for h in v['encoded_hex']]
        input_values = ['None' if index in v['missing'] else f'Some({value})'
                        for index, value in enumerate(encoded)]
        changes = ['{ index: ' + str(c['index']) + ', old_data: ' + shard(c['old_hex'])
                   + ', new_data: ' + shard(c['new_hex']) + ' }' for c in v['changes']]
        lines.extend([
            '', '///|', f'test "Go v1.14.2 parity recovery and update vector {i}: {v["k"]}+{v["m"]}/{v["length"]}" {{',
            f'  let codec = try! @moonerasure.Codec::new({v["k"]}, {v["m"]})',
            '  let data = ' + array(shard(h) for h in v['data_hex']),
            '  let expected = ' + array(encoded),
            '  assert_eq(try! codec.encode_all(data), expected)',
            '  let input : Array[Bytes?] = ' + array(input_values),
            '  assert_eq(try! codec.reconstruct(input), expected)',
            '  assert_eq(try! codec.reconstruct_selected(input, ' + array(map(str,v['targets'])) + '), '
            + array(shard(h) for h in v['selected_hex']) + ')',
            '  let changes : Array[@moonerasure.DataShardUpdate] = ' + array(changes),
            '  let old_parity = ' + array(shard(h) for h in v['encoded_hex'][v['k']:]),
            '  assert_eq(try! codec.update_parity(old_parity, changes), '
            + array(shard(h) for h in v['updated_parity_hex']) + ')',
            '}',
        ])
    (ROOT / 'reference_vectors_generated_test.mbt').write_text('\n'.join(lines) + '\n', encoding='utf-8', newline='\n')
    print(f'Generated {len(fixture["vectors"])} pinned reference vectors')


if __name__ == '__main__':
    main()
